import { useEffect, useState } from 'react';
import { GrafloriaDashboard } from '@grafloria/react';
import type { DashboardOptions, DashboardViewSpec } from '@grafloria/element';
import { markReady } from '../ready';

/** THE OPTIONS PAGE. dashboard-builder is deliberately plain — one flat
 *  12-column grid. This page is where the ADVANCED grid constructs live, each a
 *  labelled tab so a reader can see which option produces which behaviour:
 *  gravity packing, float mode, right-to-left boards, responsive columns and
 *  pinned widgets — all through the same [options] the kit exposes. */
const tile = (id: string, label: string, span: number, rows = 1, pinned = false) =>
  ({ id, kind: 'tile', span, rows, pinned, title: label, data: { label } });

const views: DashboardViewSpec[] = [
  { id: 'pack', name: 'Gravity pack', widgets: [
    tile('p1', 'A · span 6', 6, 2), tile('p2', 'B · span 3', 3),
    tile('p3', 'C · span 3', 3), tile('p4', 'D · span 4', 4),
    tile('p5', 'E · span 8', 8), tile('p6', 'F · span 12', 12),
  ]},
  { id: 'wide', name: 'Wide cells', columns: 6, widgets: [
    tile('w1', 'half', 3, 2), tile('w2', 'half', 3),
    tile('w3', 'third', 2), tile('w4', 'two-thirds', 4),
    tile('w5', 'full', 6),
  ]},
  { id: 'pinned', name: 'Pinned', widgets: [
    tile('k1', 'PINNED — survives reflow', 4, 2, true),
    tile('k2', 'flows', 4), tile('k3', 'flows', 4),
    tile('k4', 'flows', 6), tile('k5', 'flows', 6),
  ]},
  { id: 'dense', name: 'Dense mix', widgets: [
    tile('d1', 'lead', 8, 2), tile('d2', 'side', 4),
    tile('d3', 'side', 4), tile('d4', 'q', 3), tile('d5', 'q', 3),
    tile('d6', 'q', 3), tile('d7', 'q', 3),
  ]},
];

const options: Partial<DashboardOptions> = {
  columns: 12,
  gap: 8,
  sizing: 'grow',
  rowHeight: 96,
  float: false,
  responsive: { columnWidth: 96 },
  renderWidget: (w, host) => {
    const label = (w.data as { label?: string })?.label ?? w.title ?? 'Tile';
    host.innerHTML =
      `<div style="height:100%;display:flex;align-items:center;justify-content:center;` +
      `border-radius:10px;font:600 13px/1.3 system-ui,sans-serif;color:#3c4254;` +
      `background:linear-gradient(135deg,#f6f7fb,#eef1fe);` +
      `border:1px solid #d8dce6;text-align:center;padding:8px">${label}</div>`;
  },
};

export default function GridOptionsDemo() {
  const [tab] = useState<string>('pack');
  useEffect(() => markReady(), []);
  return (
    <GrafloriaDashboard views={views} options={options} activeView={tab}
      style={{ display: 'block', height: '100vh' }} />
  );
}

dashboard/kanban-board.text:
import { useEffect, useRef } from 'react';
import { GrafloriaDashboard, type WidgetProps } from '@grafloria/react';
import type { DashboardHandle, DashboardOptions, DashboardViewSpec, DashboardWidgetSpec } from '@grafloria/element';
import { markReady } from '../ready';

// KANBAN BOARD. Every column is a CONTAINER with `columns: 1` and gravity
// on (float off), so its cards stack top-down, close the gap a card leaves, and
// reorder by push. Cards are `autoHeight` and rendered by a React component
// (widgetTypes): the kit re-measures when the portal content arrives. `canDrop`
// keeps cards inside columns and refuses a column at its WIP limit.

const ROW = 8;        // row unit, px
const HEAD_ROWS = 3;  // header band: 36 px of header + 12 px of air above the first card
const GAP = 8;
const EMPTY_ROWS = 30; // a stage's inner height in rows when its cards need less: room to drop into
const GUESS = 4;      // a card's first-guess rows; autoHeight measures it
interface Col { id: string; name: string; wip?: number; tint: string }
interface Card { title: string; desc?: string; tag?: string; who?: string }
const COLUMNS: Col[] = [
  { id: 'backlog', name: 'Backlog', tint: 'var(--kb-st-backlog, #eceff5)' },
  { id: 'doing',   name: 'In progress', wip: 3, tint: 'var(--kb-st-doing, #e6eefc)' },
  { id: 'review',  name: 'Review',      wip: 2, tint: 'var(--kb-st-review, #fbf1df)' },
  { id: 'done',    name: 'Done', tint: 'var(--kb-st-done, #e4f3ea)' },
];
const CARDS: Record<string, Card[]> = {
  backlog: [
    { title: 'Export the board as PDF', tag: 'export', who: 'RO' },
    { title: 'Keyboard shortcuts for moving a card between columns', desc: 'Ctrl+← / Ctrl+→ moves the focused card; the screen reader announces the new column and position.', tag: 'a11y', who: 'MS' },
    { title: 'Swimlanes by assignee', tag: 'idea', who: 'LK' },
  ],
  doing: [
    { title: 'Content-driven card height', desc: 'Cards measure their content and take whole rows.', tag: 'kit', who: 'RO' },
    { title: 'WIP limits per column', tag: 'kit', who: 'MS' },
  ],
  review: [
    { title: 'Undo a cross-column move in one step', tag: 'kit', who: 'LK' },
  ],
  done: [],
};
const NEW_TITLES = ['Follow up with the design review', 'Fix the flaky timing test', 'Write the release notes', 'Try a 6-column board on a phone'];

const CSS = `
.kb-card { box-sizing: border-box; height: 100%; padding: 8px 10px; border-radius: 8px;
  background: var(--kb-card, #fff); border: 1px solid var(--kb-line, #dfe3ea);
  font: 13px/1.35 system-ui, sans-serif; color: var(--kb-ink, #1d2330); overflow: hidden; }
.kb-card .t { font-weight: 600; margin-bottom: 4px; }
.kb-card .d { color: var(--kb-muted, #5d6576); font-size: 12px; margin-bottom: 6px; }
.kb-card .m { display: flex; gap: 6px; align-items: center; font-size: 11px; color: var(--kb-muted, #5d6576); }
.kb-card .tag { padding: 1px 6px; border-radius: 999px; background: var(--kb-tag, #eef1fb); color: #3b52d9; }
.kb-card .who { margin-left: auto; width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center;
  background: #3b52d9; color: #fff; font-size: 10px; font-weight: 600; }
.kb-head { display: flex; align-items: center; gap: 8px; height: calc(100% - 12px); padding: 0 6px; white-space: nowrap; overflow: hidden;
  font: 600 13px system-ui, sans-serif; color: var(--kb-ink, #1d2330); }
.kb-head .n { font-weight: 500; color: var(--kb-muted, #5d6576); font-variant-numeric: tabular-nums; }
.kb-head .n.over { color: #c2410c; font-weight: 700; }
.kb-head > span:first-child { overflow: hidden; text-overflow: ellipsis; }
.kb-head button { flex: none; margin-left: auto; border: 1px solid var(--kb-line, #dfe3ea); background: transparent; color: inherit;
  border-radius: 6px; padding: 2px 8px; cursor: pointer; font: inherit; font-weight: 500; }
@media (prefers-color-scheme: dark) {
  :root { --kb-st-backlog: #1e222a; --kb-st-doing: #1a2436; --kb-st-review: #2b2417; --kb-st-done: #18271f; --kb-card: #1f232b; --kb-line: #353b47; --kb-ink: #e6e9ef; --kb-muted: #9aa3b5; --kb-tag: #27305a; }
}`;

/** A card — a real React component, portal-mounted into the kit's host. */
function KanbanCard({ data }: WidgetProps) {
  const d = data as unknown as Card;
  return (
    <div className="kb-card">
      <div className="t">{d.title}</div>
      {d.desc ? <div className="d">{d.desc}</div> : null}
      <div className="m">
        <span className="tag">{d.tag ?? 'task'}</span>
        <span className="who">{d.who ?? '?'}</span>
      </div>
    </div>
  );
}
const widgetTypes = { card: KanbanCard };

let seq = 0;
const cardSpec = (d: Card): DashboardWidgetSpec =>
  ({ id: `card-${++seq}`, kind: 'card', span: 1, rows: GUESS, resizable: false, data: d as unknown as Record<string, unknown> });

export default function KanbanBoardDemo() {
  const handleRef = useRef<DashboardHandle | null>(null);
  const heads = useRef(new Map<string, { n: HTMLElement; add: HTMLButtonElement }>());

  // Built once per mount: the board, its policy and its header painter share
  // the handle through refs, exactly as the JS page shares `H`.
  const board = useRef<{ views: DashboardViewSpec[]; options: Partial<DashboardOptions>; updateCounts: () => void } | null>(null);
  if (!board.current) {
    seq = 0;
    const countsNow = (): Record<string, number> => {
      const out: Record<string, number> = {};
      const view = handleRef.current?.toJSON().views[0];
      for (const c of COLUMNS) out[c.id] = (view?.widgets.find((w) => w.id === c.id)?.widgets ?? []).length;
      return out;
    };
    const isFull = (columnId: string) => {
      const c = COLUMNS.find((x) => x.id === columnId);
      return !!c?.wip && countsNow()[columnId] >= c.wip;
    };
    const updateCounts = () => {
      if (!handleRef.current) return;
      const counts = countsNow();
      for (const c of COLUMNS) {
        const h = heads.current.get(c.id);
        if (!h) continue;
        const full = !!c.wip && counts[c.id] >= c.wip;
        h.n.textContent = c.wip ? `${counts[c.id]} / ${c.wip}${full ? ' · full' : ''}` : String(counts[c.id]);
        h.n.classList.toggle('over', full);
        h.add.hidden = full; // a full column takes no new card — the count says why
      }
    };
    const addCard = (columnId: string) => {
      const H = handleRef.current;
      if (!H || isFull(columnId)) return undefined;
      const d: Card = { title: NEW_TITLES[seq % NEW_TITLES.length], tag: 'new', who: 'RO' };
      // No cell given: the kit auto-positions — with gravity that is the bottom of the list.
      const w = H.addWidget(cardSpec(d), columnId);
      updateCounts();
      return w;
    };
    const paintHead = (sectionId: string, host: HTMLElement) => {
      const col = COLUMNS.find((c) => c.id === sectionId);
      if (!col) return;
      host.replaceChildren();
      const el = document.createElement('div'); el.className = 'kb-head';
      const name = document.createElement('span'); name.textContent = col.name;
      const n = document.createElement('span'); n.className = 'n';
      const add = document.createElement('button'); add.textContent = '+ Add'; add.dataset.axdbPass = '';
      add.title = `Add a card to ${col.name}`;
      add.addEventListener('click', (e) => { e.stopPropagation(); addCard(col.id); });
      el.append(name, n, add); host.append(el);
      heads.current.set(sectionId, { n, add });
      updateCounts();
    };
    board.current = {
      views: [{
        id: 'main',
        widgets: COLUMNS.map((c) => {
          // A section's slab is sized in the PARENT's rows: a header of
          // HEAD_ROWS × (ROW + GAP) and inner + HEAD_ROWS parent rows give inner
          // rows of exactly ROW. `maxRows` is the empty column's height.
          const inner = Math.max(EMPTY_ROWS, CARDS[c.id].length * GUESS);
          return {
            id: c.id, title: c.name, span: 3, rows: inner + HEAD_ROWS, columns: 1, pinned: true, movable: 'row', resizable: false,
    background: c.tint, stack: true, // a stage only trades places with the others; a tinted list
            caption: { text: c.name, height: HEAD_ROWS * (ROW + GAP), background: 'transparent', border: 'none' },
            maxRows: EMPTY_ROWS,
            widgets: CARDS[c.id].map(cardSpec),
          } as DashboardWidgetSpec;
        }),
      }],
      options: {
        columns: 12,
        gap: GAP,
        sizing: 'grow',
        rowHeight: ROW,
        float: false,
        autoHeight: true,
        // The drop policy: cards live in columns, and a column at its WIP limit takes no more.
        canDrop: ({ to }) => COLUMNS.some((c) => c.id === to) && !isFull(to),
        renderCaption: (w, host) => paintHead(w.id, host),
      },
      updateCounts,
    };
  }
  const { updateCounts } = board.current;

  useEffect(() => {
    // The first measure needs two frames after mount; markReady adds two more.
    let alive = true;
    requestAnimationFrame(() => requestAnimationFrame(() => {
      if (!alive) return;
      updateCounts();
      markReady();
    }));
    return () => { alive = false; };
  }, [updateCounts]);

  return (
    <div style={{ height: '100vh', minHeight: 560 }}>
      <style>{CSS}</style>
      <GrafloriaDashboard
        views={board.current.views}
        options={board.current.options}
        widgetTypes={widgetTypes}
        onReady={(h) => {
          handleRef.current = h;
          (window as unknown as { __lab?: unknown }).__lab = { H: h };
          updateCounts();
        }}
        onLayoutChange={() => updateCounts()}
      />
    </div>
  );
}

styling/turbo-flow.text:
import { useEffect } from 'react';
import { GrafloriaFlow, DARK_THEME } from '@grafloria/react';
import type { LinearGradient, Shadow } from '@grafloria/engine';
import { markReady } from '../ready';

const TURBO: LinearGradient = {
  type: 'linear', x1: 0, y1: 0, x2: 1, y2: 0,
  stops: [{ offset: 0, color: '#2a8af6' }, { offset: 0.5, color: '#a853ba' }, { offset: 1, color: '#e92a67' }],
};
const GLOW: Shadow = { offsetX: 0, offsetY: 0, blur: 6, color: '#a853ba' };

const node = (id: string, x: number, y: number, label: string) => ({
  id, position: { x, y }, size: { width: 170, height: 72 }, data: { label },
  style: {
    fill: '#111528', stroke: '#2a8af6', strokeWidth: 2,
    animatedBorder: true, borderAnimationType: 'gradient' as const, shadow: GLOW,
  },
});
const edge = (id: string, s: string, t: string) => ({
  id, source: s, target: t,
  style: { stroke: TURBO, strokeWidth: 3, shadow: GLOW, animation: { type: 'dash-flow', speed: 'fast' } as const },
});

const nodes = [node('a', 60, 90, 'Source'), node('b', 380, 60, 'Turbo'), node('c', 380, 210, 'Boost'), node('d', 700, 130, 'Sink')];
const edges = [edge('e1', 'a', 'b'), edge('e2', 'a', 'c'), edge('e3', 'b', 'd'), edge('e4', 'c', 'd')];

/** Glowing, animated gradient edges and node borders — all through the public
 *  style API: gradient stroke paint servers, drop-shadow glow filters, and a
 *  live dash-flow keyframe streaming along each edge. */
export default function TurboFlowDemo() {
  useEffect(() => markReady(), []);
  return (
    <div style={{ height: '100vh', background: '#0b1220' }}>
      <GrafloriaFlow defaultNodes={nodes} defaultEdges={edges} theme={DARK_THEME} />
    </div>
  );
}

collab/conflict-resolution.text:
import { useCallback, useMemo, useRef, useState } from 'react';
import { GrafloriaFlow } from '@grafloria/react';
import type { DiagramInstance } from '@grafloria/react';
import { MemoryHub } from '@grafloria/element';
import { markReady } from '../ready';

/** Conflict resolution: two peers edit the SAME node at the SAME time — one
 *  moves it, the other renames it — offline from each other (batched with a
 *  huge interval so nothing crosses the wire until ⇄ Exchange flushes both op
 *  logs). Both converge with BOTH edits intact, because a per-property CRDT
 *  keeps position and label as different registers. */
const nodeSpec = () => [{ id: 'n1', label: 'Draft', position: { x: 120, y: 120 }, size: { width: 160, height: 70 } }];

export default function ConflictResolutionDemo() {
  const instA = useRef<DiagramInstance | null>(null);
  const instB = useRef<DiagramInstance | null>(null);
  const sessionA = useRef<{ flush: () => void } | null>(null);
  const sessionB = useRef<{ flush: () => void } | null>(null);
  const [name, setName] = useState('Final');
  const [statA, setStatA] = useState('');
  const [statB, setStatB] = useState('');
  const [verdict, setVerdict] = useState('');

  const { collabA, collabB } = useMemo(() => {
    const hub = new MemoryHub();
    return {
      collabA: { transport: hub.connect('ana'), actor: 'ana', batch: { intervalMs: 1_000_000 } },
      collabB: { transport: hub.connect('bo'), actor: 'bo', batch: { intervalMs: 1_000_000 } },
    };
  }, []);

  const nodeOf = (i: DiagramInstance | null): any => (i?.getModel() as any)?.getNode('n1');
  const stateOf = (i: DiagramInstance | null) => {
    const n = nodeOf(i);
    return n ? { label: n.getMetadata('label'), x: Math.round(n.position.x), w: n.size.width } : { label: '?', x: 0, w: 0 };
  };

  const refresh = useCallback(() => {
    const a = stateOf(instA.current);
    const b = stateOf(instB.current);
    const d = { lbl: a.label !== b.label, x: a.x !== b.x, w: a.w !== b.w };
    const chip = (s: { label: string; x: number; w: number }) =>
      `label <b${d.lbl ? ' style="color:#e0245e"' : ''}>"${s.label}"</b> · x <b${d.x ? ' style="color:#e0245e"' : ''}>${s.x}</b> · w <b${d.w ? ' style="color:#e0245e"' : ''}>${s.w}</b>`;
    setStatA(chip(a));
    setStatB(chip(b));
    const converged = !d.lbl && !d.x && !d.w;
    const edited = !(a.label === 'Draft' && a.x === 120 && a.w === 160);
    setVerdict(!converged
      ? '<span style="color:#b45309">● diverged — the peers hold different values until you ⇄ Exchange</span>'
      : edited
        ? '<span style="color:#16a34a;font-weight:600">✓ converged — every edit survived on BOTH peers</span>'
        : 'in sync — both peers agree (boot state)');
  }, []);

  const moveA = () => { nodeOf(instA.current)?.setPosition(360, 250); refresh(); };
  const renameB = () => { nodeOf(instB.current)?.setMetadata('label', (name || 'Final').trim() || 'Final'); refresh(); };
  const resizeA = () => { nodeOf(instA.current)?.setSize(220, 90); refresh(); };
  const exchange = () => {
    sessionA.current?.flush();
    sessionB.current?.flush();
    requestAnimationFrame(() => { instA.current?.renderNow(); instB.current?.renderNow(); refresh(); });
  };
  const resetAll = () => {
    for (const i of [instA.current, instB.current]) {
      const n = nodeOf(i);
      if (n) { n.setPosition(120, 120); n.setSize(160, 70); n.setMetadata('label', 'Draft'); }
    }
    sessionA.current?.flush(); sessionB.current?.flush();
    requestAnimationFrame(() => { instA.current?.renderNow(); instB.current?.renderNow(); setName('Final'); refresh(); });
  };

  const btn = { padding: '5px 11px', borderRadius: 6, border: '1px solid rgba(127,127,127,.4)', background: 'transparent', color: 'inherit', cursor: 'pointer', fontSize: 12 } as const;
  const chipLabel = { font: '11px ui-monospace,Menlo,monospace', background: 'rgba(37,99,235,.85)', color: '#fff', padding: '2px 8px', borderRadius: 4 } as const;

  return (
    <div>
      <div style={{ fontSize: 12, opacity: .8, padding: '10px 14px', borderBottom: '1px solid rgba(127,127,127,.25)' }}>
        Peer A moves n1, peer B renames it — offline. Their chips disagree until ⇄ Exchange, then both converge with both edits intact.
      </div>
      <div style={{ display: 'flex', height: 'calc(100vh - 150px)' }}>
        <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', borderRight: '2px solid rgba(127,127,127,.35)' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '8px 10px', borderBottom: '1px solid rgba(127,127,127,.25)' }}>
            <span style={chipLabel}>peer A — moves it</span>
            <button onClick={moveA} style={btn}>⤢ Move node</button>
            <span style={{ marginLeft: 'auto', font: '12px ui-monospace,Menlo,monospace', opacity: .85 }} dangerouslySetInnerHTML={{ __html: statA }} />
          </div>
          <GrafloriaFlow defaultNodes={nodeSpec()} defaultEdges={[]} collab={collabA as never}
            style={{ display: 'block', flex: 1 }}
            onInit={(i) => { instA.current = i; refresh(); markReady(); }}
            onCollabReady={(s) => { sessionA.current = s as never; }} />
        </div>
        <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '8px 10px', borderBottom: '1px solid rgba(127,127,127,.25)' }}>
            <span style={chipLabel}>peer B — renames it</span>
            <input value={name} onChange={(e) => setName(e.target.value)}
              style={{ fontSize: 12, padding: '4px 7px', width: 90, border: '1px solid rgba(127,127,127,.4)', borderRadius: 6, background: 'transparent', color: 'inherit' }} />
            <button onClick={renameB} style={btn}>✎ Rename</button>
            <span style={{ marginLeft: 'auto', font: '12px ui-monospace,Menlo,monospace', opacity: .85 }} dangerouslySetInnerHTML={{ __html: statB }} />
          </div>
          <GrafloriaFlow defaultNodes={nodeSpec()} defaultEdges={[]} collab={collabB as never}
            style={{ display: 'block', flex: 1 }}
            onInit={(i) => { instB.current = i; refresh(); }}
            onCollabReady={(s) => { sessionB.current = s as never; }} />
        </div>
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '9px 14px', borderTop: '1px solid rgba(127,127,127,.3)' }}>
        <button onClick={exchange} style={{ ...btn, border: '1px solid rgba(37,99,235,.6)', fontWeight: 600 }}>⇄ Exchange / Sync</button>
        <button onClick={resetAll} style={btn}>↺ Reset</button>
        <button onClick={resizeA} style={btn}>＋ Resize n1</button>
        <span style={{ marginLeft: 8, fontSize: 13 }} dangerouslySetInnerHTML={{ __html: verdict }} />
      </div>
    </div>
  );
}

collab/live-cursors.text:
import { useEffect, useMemo } from 'react';
import { GrafloriaFlow } from '@grafloria/react';
import { MemoryHub } from '@grafloria/element';
import { markReady } from '../ready';

/** Live cursors with no server: two canvases join the same MemoryHub room via
 *  collab. Move the pointer over the left canvas and the cursor appears live in
 *  the right one — remote cursors live on a separate presence DOM layer, so
 *  60Hz cursor traffic never repaints the diagram and never enters the op log. */
const spec = () => ([
  { id: 'a', label: 'Plan',  position: { x: 70,  y: 90 }, size: { width: 150, height: 66 } },
  { id: 'b', label: 'Build', position: { x: 320, y: 90 }, size: { width: 150, height: 66 } },
]);
const edges = [{ id: 'e1', source: 'a', target: 'b' }];
const badge = { position: 'absolute', top: 8, left: 8, zIndex: 2, font: '11px ui-monospace,Menlo,monospace', background: 'rgba(37,99,235,.85)', color: '#fff', padding: '2px 8px', borderRadius: 4 } as const;

export default function LiveCursorsDemo() {
  useEffect(() => markReady(), []);
  const { collabA, collabB } = useMemo(() => {
    const hub = new MemoryHub();
    return {
      collabA: { transport: hub.connect('ana'), actor: 'ana', batch: false, awarenessThrottleMs: 0, presence: { name: 'Ana', smoothing: 0 } },
      collabB: { transport: hub.connect('bo'), actor: 'bo', batch: false, awarenessThrottleMs: 0, presence: { name: 'Bo', smoothing: 0 } },
    };
  }, []);
  return (
    <div>
      <div style={{ fontSize: 12, opacity: .8, padding: '10px 24px', borderBottom: '1px solid rgba(127,127,127,.25)' }}>
        Move your pointer over the left canvas — your cursor appears live in the right one.
      </div>
      <div style={{ display: 'flex', height: 'calc(100vh - 45px)' }}>
        <div style={{ flex: 1, minWidth: 0, position: 'relative', borderRight: '2px solid rgba(127,127,127,.35)' }}>
          <span style={badge}>Ana (you)</span>
          <GrafloriaFlow defaultNodes={spec()} defaultEdges={edges} collab={collabA as never} style={{ display: 'block', height: '100%' }} />
        </div>
        <div style={{ flex: 1, minWidth: 0, position: 'relative' }}>
          <span style={badge}>Bo (sees Ana)</span>
          <GrafloriaFlow defaultNodes={spec()} defaultEdges={structuredClone(edges)} collab={collabB as never} style={{ display: 'block', height: '100%' }} />
        </div>
      </div>
    </div>
  );
}

collab/offline-and-reconnect.text:
import { useEffect, useMemo } from 'react';
import { GrafloriaFlow } from '@grafloria/react';
import { MemoryHub } from '@grafloria/element';
import { markReady } from '../ready';

/** Offline & reconnect: two peers on one MemoryHub via collab. Anti-entropy
 *  exchanges exactly the ops each side missed and the two converge — no lost
 *  edits, no full resend. Offline edits are held in the local op log; the
 *  reconnect's sync round delivers them. */
const spec = () => ([
  { id: 'a', label: 'Alpha', position: { x: 80,  y: 90 }, size: { width: 150, height: 66 } },
  { id: 'b', label: 'Beta',  position: { x: 320, y: 90 }, size: { width: 150, height: 66 } },
]);
const edges = [{ id: 'e1', source: 'a', target: 'b' }];
const badge = { position: 'absolute', top: 8, left: 8, zIndex: 2, font: '11px ui-monospace,Menlo,monospace', background: 'rgba(37,99,235,.85)', color: '#fff', padding: '2px 8px', borderRadius: 4 } as const;

export default function OfflineAndReconnectDemo() {
  useEffect(() => markReady(), []);
