import { useRef, useState } from 'react';
import { GrafloriaFlow } from '@grafloria/react';
import type { DiagramInstance } from '@grafloria/react';
import { markReady } from '../ready';

/** Download image: exports the VNode tree — labels, arrowheads, shadows and all
 *  — not a screenshot. PNG (raster) and SVG (vector) both come from the same
 *  instance.export() pipeline. */
const SHADOW = { offsetX: 3, offsetY: 4, blur: 5, color: '#1e293b' };

const nodes = [
  { id: 'ingest',    label: 'Ingest',    position: { x: 60,  y: 100 }, size: { width: 170, height: 78 }, style: { fill: '#dbeafe', stroke: '#2563eb', strokeWidth: 2 } },
  { id: 'transform', label: 'Transform', position: { x: 340, y: 100 }, size: { width: 170, height: 78 }, style: { fill: '#ffffff', stroke: '#0f172a', strokeWidth: 2, shadow: SHADOW } },
  { id: 'publish',   label: 'Publish',   position: { x: 620, y: 100 }, size: { width: 170, height: 78 }, style: { fill: '#dcfce7', stroke: '#16a34a', strokeWidth: 2 } },
];
const edges = [
  { id: 'e1', source: 'ingest', target: 'transform', label: 'rows' },
  { id: 'e2', source: 'transform', target: 'publish' },
];

function download(href: string, name: string) {
  const a = document.createElement('a');
  a.href = href; a.download = name; a.click();
}

export default function DownloadImageDemo() {
  const instanceRef = useRef<DiagramInstance | null>(null);
  const [note, setNote] = useState('Exports the VNode tree — not a screenshot.');

  const downloadPng = async () => {
    const d = await instanceRef.current!.export('png', { scale: 2 });
    download(d, 'diagram.png');
    setNote(`diagram.png saved (${Math.round(d.length * 3 / 4 / 1024)} KB)`);
  };
  const downloadSvg = async () => {
    const svg = await instanceRef.current!.export('svg');
    download('data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg), 'diagram.svg');
    setNote(`diagram.svg saved (${Math.round(svg.length / 1024)} KB)`);
  };

  const btn = { padding: '6px 14px', borderRadius: 6, border: '1px solid rgba(127,127,127,.4)', background: 'transparent', color: 'inherit', cursor: 'pointer', font: 'inherit' } as const;
  return (
    <div>
      <div style={{ display: 'flex', gap: 8, alignItems: 'center', padding: '10px 24px', borderBottom: '1px solid rgba(127,127,127,.25)', flexWrap: 'wrap' }}>
        <button onClick={downloadPng} style={btn}>download PNG</button>
        <button onClick={downloadSvg} style={btn}>download SVG</button>
        <span style={{ font: '12px ui-monospace,monospace', opacity: .8 }}>{note}</span>
      </div>
      <GrafloriaFlow
        defaultNodes={nodes}
        defaultEdges={edges}
        style={{ display: 'block', height: 'calc(100vh - 45px)' }}
        onInit={(instance) => { instanceRef.current = instance; markReady(); }}
      />
    </div>
  );
}

misc/editable-round-trip.text:
import { useState } from 'react';
import { GrafloriaFlow } from '@grafloria/react';
import type { DiagramInstance } from '@grafloria/react';
import { importDiagram, isEditableArtifact } from '@grafloria/element';
import { markReady } from '../ready';

/** Editable round-trip: the model rides INSIDE the exported file — an SVG
 *  <metadata> block. Re-open that file and you get an editable diagram back,
 *  not a flat picture. Pane A is the original; pane B is re-opened purely from
 *  pane A's exported bytes. */
const WHEN = '2020-01-01T00:00:00Z';

const nodesA = [
  { id: 'a', label: 'Author',  position: { x: 60,  y: 90 },  size: { width: 150, height: 66 } },
  { id: 'b', label: 'Review',  position: { x: 300, y: 90 },  size: { width: 150, height: 66 } },
  { id: 'c', label: 'Publish', position: { x: 300, y: 230 }, size: { width: 150, height: 66 } },
];
const edgesA = [{ id: 'e1', source: 'a', target: 'b' }, { id: 'e2', source: 'b', target: 'c' }];

const badge = { position: 'absolute', top: 8, left: 8, zIndex: 2, font: '11px ui-monospace,Menlo,monospace', background: 'rgba(37,99,235,.85)', color: '#fff', padding: '2px 8px', borderRadius: 4 } as const;

export default function EditableRoundTripDemo() {
  const [nodesB, setNodesB] = useState<unknown[]>([]);
  const [edgesB, setEdgesB] = useState<unknown[]>([]);
  const [status, setStatus] = useState('exporting…');

  const onInitA = async (instance: DiagramInstance) => {
    try {
      const svg = await instance.export('svg', { embedModel: true, embedModelCreatedAt: WHEN } as never);
      const editable = isEditableArtifact(svg);
      const model = importDiagram(svg) as any;
      if (model) {
        setNodesB(model.getNodes().map((n: any) => ({
          id: n.id, label: n.getMetadata('label'),
          position: { x: n.position.x, y: n.position.y },
          size: { width: n.size.width, height: n.size.height },
        })));
        setEdgesB(model.getLinks().map((l: any) => ({ id: l.id, source: l.sourceNodeId, target: l.targetNodeId })));
        setStatus(`re-opened ${model.getNodes().length} nodes from an ${editable ? 'editable' : 'unrecognised'} artifact.`);
      } else {
        setStatus('the exported artifact carried no embedded model.');
      }
    } catch (e) {
      setStatus('export failed: ' + (e as Error).message);
    }
    markReady();
  };

  return (
    <div>
      <div style={{ fontSize: 12, opacity: .8, padding: '10px 24px', borderBottom: '1px solid rgba(127,127,127,.25)' }}>
        The model rides inside the exported file. Re-open it and you get an editable diagram back — {status}
      </div>
      <div style={{ display: 'flex', height: 'calc(100vh - 45px)' }}>
        <div style={{ flex: 1, minWidth: 0, position: 'relative', borderRight: '2px solid rgba(127,127,127,.35)' }}>
          <span style={badge}>original</span>
          <GrafloriaFlow defaultNodes={nodesA} defaultEdges={edgesA} style={{ display: 'block', height: '100%' }} onInit={onInitA} />
        </div>
        <div style={{ flex: 1, minWidth: 0, position: 'relative' }}>
          <span style={badge}>re-opened from the exported file</span>
          <GrafloriaFlow nodes={nodesB as never} edges={edgesB as never} style={{ display: 'block', height: '100%' }} />
        </div>
      </div>
    </div>
  );
}

misc/mermaid-viewer.text:
import { useEffect, useRef, useState } from 'react';
import { GrafloriaFlow } from '@grafloria/react';
import { importDiagramText } from '@grafloria/element';
import { markReady } from '../ready';
import { mountCodeEditor } from '../code-editor';

/** Mermaid viewer: paste Mermaid text and see it rendered. importDiagramText()
 *  parses the source into a model; the canvas renders the reconciled spec.
 *  Unsupported diagram types report their reason rather than throwing. */
const EXAMPLES: Record<string, string> = {
  flowchart: `flowchart TD
  Start([Start]) --> Load[(Fetch data)]
  Load --> Check{Valid?}
  Check -->|yes| Save[[Persist]]
  Check -->|no| Start
  Save --> Done((Done))
  style Start fill:#c8e6c9,stroke:#2e7d32
  style Done fill:#bbdefb,stroke:#1565c0
  classDef warn fill:#ffe0b2,stroke:#e65100
  class Check warn`,
  'flowchart-fancy': `flowchart LR
  subgraph pipeline
    Extract --> Transform --> Load
  end
  Load --> Warehouse[(Warehouse)]
  Trigger --> Extract`,
  er: `erDiagram
  CUSTOMER ||--o{ ORDER : places
  ORDER ||--|{ LINE_ITEM : contains
  CUSTOMER {
    string name
    string email
  }`,
  class: `classDiagram
  class Animal {
    +int age
    +String name
    +bark() void
  }
  class Dog
  class Cat
  Animal <|-- Dog
  Animal <|-- Cat`,
  state: `stateDiagram-v2
  [*] --> Still
  Still --> Moving
  Moving --> Still
  Moving --> Crash
  Crash --> [*]`,
  sequence: `sequenceDiagram
  Alice->>Bob: Hello Bob
  Bob-->>Alice: Hi Alice`,
};

export default function MermaidViewerDemo() {
  const [type, setType] = useState('flowchart');
  const [text, setText] = useState(EXAMPLES['flowchart']);
  const [nodes, setNodes] = useState<unknown[]>([]);
  const [edges, setEdges] = useState<unknown[]>([]);
  const [status, setStatus] = useState('—');
  const [bad, setBad] = useState(false);

  const renderText = (src: string) => {
    const r = importDiagramText(src) as any;
    if (r.unsupported) {
      setBad(true);
      setStatus(`unsupported diagram type: ${r.unsupported}`);
      setNodes([]);
      setEdges([]);
      return;
    }
    setBad(false);
    const model = r.diagram;
    setNodes(model.getNodes().map((n: any) => ({
      id: n.id, label: n.getMetadata('label'),
      position: { x: n.position.x, y: n.position.y },
      size: { width: n.size.width, height: n.size.height },
      shape: n.getMetadata('shape'), style: n.style,
    })));
    setEdges(model.getLinks().map((l: any) => ({ id: l.id, source: l.sourceNodeId, target: l.targetNodeId })));
    setStatus(`${model.getNodes().length} nodes · ${model.getLinks().length} links`);
  };

  useEffect(() => { renderText(EXAMPLES['flowchart']); markReady(); }, []);
  // The source reads as Mermaid: the gallery's editor colours it, and the
  // textarea underneath stays the state onChange keeps.
  const source = useRef<HTMLTextAreaElement>(null);
  useEffect(() => { void mountCodeEditor(source.current, { language: 'mermaid' }); }, []);

  const load = (t: string) => { setType(t); const src = EXAMPLES[t]; setText(src); renderText(src); };
  const apply = () => renderText(text);

  const ctl = { font: 'inherit', color: 'inherit', background: 'transparent', border: '1px solid rgba(127,127,127,.4)', borderRadius: 6, padding: '4px 10px' } as const;
  return (
    <div>
      <div style={{ display: 'flex', gap: 10, padding: '8px 24px', borderBottom: '1px solid rgba(127,127,127,.25)', alignItems: 'center', flexWrap: 'wrap' }}>
        <label>diagram{' '}
          <select value={type} onChange={(e) => load(e.target.value)} style={ctl}>
